/// ```text
/// Pat =
///   IdentPat
/// | LiteralPat
/// | MacroPat
/// | OrPat
/// | ParenPat
/// | PathPat
/// | RangePat
/// | RecordPat
/// | RefPat
/// | RestPat
/// | SlicePat
/// | TuplePat
/// | TupleStructPat
/// | WildcardPat
/// ```
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Pat<'t> {
    IdentPat(IdentPat<'t>),
    LiteralPat(LiteralPat<'t>),
    MacroPat(MacroPat<'t>),
    OrPat(OrPat<'t>),
    ParenPat(ParenPat<'t>),
    PathPat(PathPat<'t>),
    RangePat(RangePat<'t>),
    RecordPat(RecordPat<'t>),
    RefPat(RefPat<'t>),
    RestPat(RestPat<'t>),
    SlicePat(SlicePat<'t>),
    TuplePat(TuplePat<'t>),
    TupleStructPat(TupleStructPat<'t>),
    WildcardPat(WildcardPat<'t>),
}

impl<'t> AstNode<'t> for Pat<'t> {
    fn can_cast(kind: SyntaxKind) -> bool {
        matches!(
            kind,
            IDENT_PAT
                | LITERAL_PAT
                | MACRO_PAT
                | OR_PAT
                | PAREN_PAT
                | PATH_PAT
                | RANGE_PAT
                | RECORD_PAT
                | REF_PAT
                | REST_PAT
                | SLICE_PAT
                | TUPLE_PAT
                | TUPLE_STRUCT_PAT
                | WILDCARD_PAT
        )
    }
    fn cast(syntax: SyntaxNode<'t>) -> Option<Self> {
        let node = match syntax.kind() {
            IDENT_PAT => Pat::IdentPat(IdentPat { syntax }),
            LITERAL_PAT => Pat::LiteralPat(LiteralPat { syntax }),
            MACRO_PAT => Pat::MacroPat(MacroPat { syntax }),
            OR_PAT => Pat::OrPat(OrPat { syntax }),
            PAREN_PAT => Pat::ParenPat(ParenPat { syntax }),
            PATH_PAT => Pat::PathPat(PathPat { syntax }),
            RANGE_PAT => Pat::RangePat(RangePat { syntax }),
            RECORD_PAT => Pat::RecordPat(RecordPat { syntax }),
            REF_PAT => Pat::RefPat(RefPat { syntax }),
            REST_PAT => Pat::RestPat(RestPat { syntax }),
            SLICE_PAT => Pat::SlicePat(SlicePat { syntax }),
            TUPLE_PAT => Pat::TuplePat(TuplePat { syntax }),
            TUPLE_STRUCT_PAT => Pat::TupleStructPat(TupleStructPat { syntax }),
            WILDCARD_PAT => Pat::WildcardPat(WildcardPat { syntax }),
            _ => return None,
        };
        Some(node)
    }
    fn syntax(self) -> SyntaxNode<'t> {
        match self {
            Pat::IdentPat(it) => it.syntax(),
            Pat::LiteralPat(it) => it.syntax(),
            Pat::MacroPat(it) => it.syntax(),
            Pat::OrPat(it) => it.syntax(),
            Pat::ParenPat(it) => it.syntax(),
            Pat::PathPat(it) => it.syntax(),
            Pat::RangePat(it) => it.syntax(),
            Pat::RecordPat(it) => it.syntax(),
            Pat::RefPat(it) => it.syntax(),
            Pat::RestPat(it) => it.syntax(),
            Pat::SlicePat(it) => it.syntax(),
            Pat::TuplePat(it) => it.syntax(),
            Pat::TupleStructPat(it) => it.syntax(),
            Pat::WildcardPat(it) => it.syntax(),
        }
    }
}

