/// ```text
/// Stmt =
///   LetStmt
/// | ExprStmt
/// | Item
/// ```
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Stmt<'t> {
    LetStmt(LetStmt<'t>),
    ExprStmt(ExprStmt<'t>),
    Item(Item<'t>),
}

impl<'t> AstNode<'t> for Stmt<'t> {
    fn can_cast(kind: SyntaxKind) -> bool {
        matches!(kind, LET_STMT | EXPR_STMT) || Item::can_cast(kind)
    }
    fn cast(syntax: SyntaxNode<'t>) -> Option<Self> {
        let node = match syntax.kind() {
            LET_STMT => Stmt::LetStmt(LetStmt { syntax }),
            EXPR_STMT => Stmt::ExprStmt(ExprStmt { syntax }),
            kind if Item::can_cast(kind) => Stmt::Item(Item::cast(syntax)?),
            _ => return None,
        };
        Some(node)
    }
    fn syntax(self) -> SyntaxNode<'t> {
        match self {
            Stmt::LetStmt(it) => it.syntax(),
            Stmt::ExprStmt(it) => it.syntax(),
            Stmt::Item(it) => it.syntax(),
        }
    }
}

impl<'t> From<LetStmt<'t>> for Stmt<'t> {
    fn from(node: LetStmt<'t>) -> Self {
        Stmt::LetStmt(node)
    }
}

impl<'t> From<ExprStmt<'t>> for Stmt<'t> {
    fn from(node: ExprStmt<'t>) -> Self {
        Stmt::ExprStmt(node)
    }
}

impl<'t> From<Item<'t>> for Stmt<'t> {
    fn from(node: Item<'t>) -> Self {
        Stmt::Item(node)
    }
}

/// ```text
/// Type =
///   ArrayType
/// | DynTraitType
/// | FnPtrType
/// | ForType
/// | ImplTraitType
/// | InferType
/// | MacroType
/// | NeverType
/// | ParenType
/// | PathType
/// | PtrType
/// | RefType
/// | SliceType
/// | TupleType
/// ```
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Type<'t> {
    ArrayType(ArrayType<'t>),
    DynTraitType(DynTraitType<'t>),
    FnPtrType(FnPtrType<'t>),
    ForType(ForType<'t>),
    ImplTraitType(ImplTraitType<'t>),
    InferType(InferType<'t>),
    MacroType(MacroType<'t>),
    NeverType(NeverType<'t>),
    ParenType(ParenType<'t>),
    PathType(PathType<'t>),
    PtrType(PtrType<'t>),
    RefType(RefType<'t>),
    SliceType(SliceType<'t>),
    TupleType(TupleType<'t>),
}

impl<'t> AstNode<'t> for Type<'t> {
    fn can_cast(kind: SyntaxKind) -> bool {
        matches!(
            kind,
            ARRAY_TYPE
                | DYN_TRAIT_TYPE
                | FN_PTR_TYPE
                | FOR_TYPE
                | IMPL_TRAIT_TYPE
                | INFER_TYPE
                | MACRO_TYPE
                | NEVER_TYPE
                | PAREN_TYPE
                | PATH_TYPE
                | PTR_TYPE
                | REF_TYPE
                | SLICE_TYPE
                | TUPLE_TYPE
        )
    }
    fn cast(syntax: SyntaxNode<'t>) -> Option<Self> {
        let node = match syntax.kind() {
            ARRAY_TYPE => Type::ArrayType(ArrayType { syntax }),
            DYN_TRAIT_TYPE => Type::DynTraitType(DynTraitType { syntax }),
            FN_PTR_TYPE => Type::FnPtrType(FnPtrType { syntax }),
            FOR_TYPE => Type::ForType(ForType { syntax }),
            IMPL_TRAIT_TYPE => Type::ImplTraitType(ImplTraitType { syntax }),
            INFER_TYPE => Type::InferType(InferType { syntax }),
            MACRO_TYPE => Type::MacroType(MacroType { syntax }),
            NEVER_TYPE => Type::NeverType(NeverType { syntax }),
            PAREN_TYPE => Type::ParenType(ParenType { syntax }),
            PATH_TYPE => Type::PathType(PathType { syntax }),
            PTR_TYPE => Type::PtrType(PtrType { syntax }),
            REF_TYPE => Type::RefType(RefType { syntax }),
            SLICE_TYPE => Type::SliceType(SliceType { syntax }),
            TUPLE_TYPE => Type::TupleType(TupleType { syntax }),
            _ => return None,
        };
        Some(node)
    }
    fn syntax(self) -> SyntaxNode<'t> {
        match self {
            Type::ArrayType(it) => it.syntax(),
            Type::DynTraitType(it) => it.syntax(),
            Type::FnPtrType(it) => it.syntax(),
            Type::ForType(it) => it.syntax(),
            Type::ImplTraitType(it) => it.syntax(),
            Type::InferType(it) => it.syntax(),
            Type::MacroType(it) => it.syntax(),
            Type::NeverType(it) => it.syntax(),
            Type::ParenType(it) => it.syntax(),
            Type::PathType(it) => it.syntax(),
            Type::PtrType(it) => it.syntax(),
            Type::RefType(it) => it.syntax(),
            Type::SliceType(it) => it.syntax(),
            Type::TupleType(it) => it.syntax(),
        }
    }
}

impl<'t> From<ArrayType<'t>> for Type<'t> {
    fn from(node: ArrayType<'t>) -> Self {
        Type::ArrayType(node)
    }
}

