/// Fails to compile when an accessor the grammar leaves to `ext.rs` is
/// missing.
#[allow(dead_code)]
mod hand_written {
    use super::*;

    fn bin_expr_(it: BinExpr<'_>) {
        let _ = it.op();
        let _ = it.lhs();
        let _ = it.rhs();
    }
    fn for_expr_(it: ForExpr<'_>) {
        let _ = it.iterable();
        let _ = it.loop_body();
    }
    fn if_expr_(it: IfExpr<'_>) {
        let _ = it.else_branch();
        let _ = it.condition();
        let _ = it.then_branch();
    }
    fn impl_(it: Impl<'_>) {
        let _ = it.trait_ty();
        let _ = it.self_ty();
    }
    fn index_expr_(it: IndexExpr<'_>) {
        let _ = it.base();
        let _ = it.index();
    }
    fn literal_(it: Literal<'_>) {
        let _ = it.value();
    }
    fn path_segment_(it: PathSegment<'_>) {
        let _ = it.self_ty();
        let _ = it.trait_ty();
    }
    fn prefix_expr_(it: PrefixExpr<'_>) {
        let _ = it.op();
    }
    fn range_expr_(it: RangeExpr<'_>) {
        let _ = it.op();
        let _ = it.start();
        let _ = it.end();
    }
    fn range_pat_(it: RangePat<'_>) {
        let _ = it.op();
        let _ = it.start();
        let _ = it.end();
    }
    fn while_expr_(it: WhileExpr<'_>) {
        let _ = it.condition();
        let _ = it.loop_body();
    }
}
